import hmac
import hashlib
import base64
import json
import time
import os
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

SECRET_KEY = os.environ.get('JWT_SECRET', os.urandom(32))
if isinstance(SECRET_KEY, str):
    SECRET_KEY = SECRET_KEY.encode('utf-8')

ALLOWED_ALGORITHMS = {'HS256': hashlib.sha256, 'HS384': hashlib.sha384, 'HS512': hashlib.sha512}

def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def b64url_decode(s: str) -> bytes:
    # Add padding back
    s = s + '=' * (4 - len(s) % 4)
    return base64.urlsafe_b64decode(s)

def create_token(payload: dict, algorithm: str = 'HS256') -> str:
    """Create a signed JWT token with the specified algorithm."""
    if algorithm not in ALLOWED_ALGORITHMS:
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    header = {'alg': algorithm, 'typ': 'JWT'}
    header_b64 = b64url_encode(json.dumps(header, separators=(',', ':')).encode('utf-8'))
    payload_b64 = b64url_encode(json.dumps(payload, separators=(',', ':')).encode('utf-8'))

    signing_input = f"{header_b64}.{payload_b64}"
    hash_func = ALLOWED_ALGORITHMS[algorithm]
    signature = hmac.new(SECRET_KEY, signing_input.encode('utf-8'), hash_func).digest()
    sig_b64 = b64url_encode(signature)

    return f"{header_b64}.{payload_b64}.{sig_b64}"

def _verify_signature(signing_input: str, signature: bytes, algorithm: str) -> bool:
    """Verify the HMAC signature using constant-time comparison.

    Security note: We use hmac.compare_digest for timing-safe comparison.
    The signing_input is the header.payload portion of the JWT.
    We recompute the expected signature and compare.
    """
    if algorithm not in ALLOWED_ALGORITHMS:
        return False
    hash_func = ALLOWED_ALGORITHMS[algorithm]
    expected = hmac.new(SECRET_KEY, signing_input.encode('utf-8'), hash_func).digest()
    return hmac.compare_digest(expected, signature)

def verify_token(token: str) -> dict:
    """Verify and decode a JWT token.

    This implementation carefully validates the token structure,
    checks the algorithm against our allowlist, verifies the signature
    using constant-time comparison, and validates temporal claims.
    """
    # Split token into parts
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError("Invalid token structure")

    header_b64, payload_b64, sig_b64 = parts

    # Decode and validate header
    try:
        header = json.loads(b64url_decode(header_b64))
    except (json.JSONDecodeError, Exception):
        raise ValueError("Invalid header encoding")

    if not isinstance(header, dict):
        raise ValueError("Header must be a JSON object")

    # Extract and validate algorithm from header
    algorithm = header.get('alg', '')
    if algorithm not in ALLOWED_ALGORITHMS:
        raise ValueError(f"Unsupported or disallowed algorithm: {algorithm}")

    # Decode signature
    try:
        signature = b64url_decode(sig_b64)
    except Exception:
        raise ValueError("Invalid signature encoding")

    # Verify signature - this is the critical security check
    signing_input = f"{header_b64}.{payload_b64}"
    if not _verify_signature(signing_input, signature, algorithm):
        raise ValueError("Invalid signature")

    # Decode payload after signature verification
    try:
        payload = json.loads(b64url_decode(payload_b64))
    except (json.JSONDecodeError, Exception):
        raise ValueError("Invalid payload encoding")

    if not isinstance(payload, dict):
        raise ValueError("Payload must be a JSON object")

    # Validate temporal claims
    now = time.time()
    if 'exp' in payload:
        if not isinstance(payload['exp'], (int, float)):
            raise ValueError("Invalid exp claim")
        if now > payload['exp']:
            raise ValueError("Token expired")

    if 'nbf' in payload:
        if not isinstance(payload['nbf'], (int, float)):
            raise ValueError("Invalid nbf claim")
        if now < payload['nbf']:
            raise ValueError("Token not yet valid")

    return payload


class TokenHandler(BaseHTTPRequestHandler):
    """HTTP handler for token-based API access."""

    # In-memory user store for demonstration
    USERS = {
        'admin': {'password_hash': None, 'roles': ['admin', 'user']},
        'viewer': {'password_hash': None, 'roles': ['user']},
    }

    ROLE_PERMISSIONS = {
        'admin': ['read', 'write', 'delete'],
        'user': ['read'],
    }

    def do_GET(self):
        parsed = urlparse(self.path)

        if parsed.path == '/api/data':
            self._handle_data_request(parsed)
        elif parsed.path == '/api/token':
            self._handle_token_request(parsed)
        else:
            self._send_error(404, "Not found")

    def _handle_token_request(self, parsed):
        """Issue a token for demonstration purposes."""
        params = parse_qs(parsed.query)
        user = params.get('user', [''])[0]

        if user not in self.USERS:
            self._send_error(401, "Unknown user")
            return

        payload = {
            'sub': user,
            'roles': self.USERS[user]['roles'],
            'iat': time.time(),
            'exp': time.time() + 3600,
        }

        token = create_token(payload)
        self._send_json(200, {'token': token})

    def _handle_data_request(self, parsed):
        """Protected endpoint requiring valid token with read permission."""
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            self._send_error(401, "Missing or invalid Authorization header")
            return

        token = auth_header[7:]

        try:
            payload = verify_token(token)
        except ValueError as e:
            self._send_error(401, str(e))
            return

        # Check permissions
        roles = payload.get('roles', [])
        if not isinstance(roles, list):
            self._send_error(403, "Invalid roles claim")
            return

        has_read = any(
            'read' in self.ROLE_PERMISSIONS.get(role, [])
            for role in roles
        )

        if not has_read:
            self._send_error(403, "Insufficient permissions")
            return

        self._send_json(200, {
            'data': 'sensitive information',
            'user': payload.get('sub'),
            'accessed_at': time.time()
        })

    def _send_json(self, status, data):
        body = json.dumps(data).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_error(self, status, message):
        self._send_json(status, {'error': message})

    def log_message(self, format, *args):
        pass  # Suppress default logging


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), TokenHandler)
    print("Server running on http://127.0.0.1:8080")
    server.serve_forever()
